assert (Hgood : forall k : nat, (5 <= k)%nat -> (k <= 12)%nat ->
    satisfies_condition k).
{
  intros k Hk1 Hk2.
  unfold satisfies_condition.
  assert (Hk1R : (4:R) < INR k).
