    assert (H : INR 4 < INR k).
    {
      apply lt_INR.
      exact Hk1.
    }
    assert (Heq : (4:R) = INR 4).
    {
      cbv [INR].
      ring.
    }
    rewrite <- Heq.
    exact H.
  }
  assert (Hk2R : INR k <= (12:R)).
  {
    assert (H : INR k <= INR 12).
    {
      apply le_INR.
      exact Hk2.
    }
    assert (Heq : (12:R) = INR 12).
    {
      cbv [INR].
      ring.
    }
    rewrite <- Heq.
    exact H.
  }
  assert (Hs : sqrt (INR k) ^ 2 = INR k).
  {
    apply pow2_sqrt.
    apply pos_INR.
    lia.
  }
  pose proof (sqrt_pos (INR k)) as Hroot.
  nra.
}
