intros x Hx Heq.
unfold logb in *.
assert (Hlx : 0 < ln x).
{
  assert (H : ln 1 < ln x).
  {
    apply ln_increasing; lra; exact Hx.
  }
  rewrite ln_1 in H; lra.
}
assert (Hl2 : 0 < ln 2).
{
  assert (H : ln 1 < ln 2).
  {
    apply ln_increasing; lra; norm_num.
  }
  rewrite ln_1 in H; lra.
}
assert (Hl3 : 0 < ln 3).
{
  assert (H : ln 1 < ln 3).
  {
    apply ln_increasing; lra; norm_num.
  }
  rewrite ln_1 in H; lra.
}
assert (Hl8 : ln 8 = 3 * ln 2).
{
  assert (H4 : ln 4 = ln 2 + ln 2).
  {
    replace 4 with (2 * 2) by norm_num.
    rewrite ln_mult; norm_num.
  }
  replace 8 with (2 * 4) by norm_num.
  rewrite ln_mult, H4.
  ring.
}
assert (Ht : 0 < ln x / ln 2) by (apply Rdiv_pos; assumption).
assert (Hq : ln (ln x / ln 2) = ln (ln x) - ln 2).
{
  replace (ln x / ln 2) with (ln x * / ln 2) by field.
  rewrite ln_mult, ln_Rinv; try assumption.
  ring.
}
assert (Hq3 : ln ((ln x / ln 2) / 3) =
    ln (ln x / ln 2) - ln 3).
{
  replace ((ln x / ln 2) / 3) with
    ((ln x / ln 2) * / 3) by field.
  rewrite ln_mult, ln_Rinv; try assumption.
  ring.
}
assert (Hr : ln x / ln 8 = (ln x / ln 2) / 3).
{
  rewrite Hl8.
  field.
  lra.
}
rewrite Hr, Hq3, Hq, Hl8 in Heq.
assert (Hlog : 2 * ln (ln x / ln 2) = 3 * ln 3) by nra.
assert (Hpow : ln ((ln x / ln 2)^2) = ln (3^3)).
{
  rewrite (ln_pow (ln x / ln 2) Ht 2).
  rewrite (ln_pow 3 Hl3 3).
  simpl.
  nra.
}
assert (Hsq : (ln x / ln 2)^2 = 3^3).
{
  apply ln_inv; try positivity.
  exact Hpow.
}
norm_num in Hsq.
exact Hsq.
